#include "controller.hpp"
namespace academy { Controller::Controller(Device& b):board_(b){} void Controller::tick(){bool p=board_.read_button()==Level::low; if(!initialized_){initialized_=true;last_=p;board_.output.state="idle";return;} const bool edge=p&&!last_; last_=p; if(edge){if(running_){running_=false;board_.output.state="cancelled";++board_.output.events;}else{running_=true;deadline_=board_.input.now_ms+3000;board_.output.state="running";++board_.output.events;}} if(running_&&board_.input.now_ms>=deadline_){running_=false;board_.output.state="done";} if(running_){board_.output.reading=deadline_-board_.input.now_ms;board_.output.brightness=static_cast<int>(board_.output.reading/30);}else{board_.output.reading=0;board_.output.brightness=0;} board_.output.led=running_;} }
